import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"قانون مكافحة الاحتكار","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0047-反垄断法.md","filePath":"ar/0047-反垄断法.md"}'),d={name:"ar/0047-反垄断法.md"};function i(o,t,n,s,h,b){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="قانون-مكافحة-الاحتكار" tabindex="-1">قانون مكافحة الاحتكار <a class="header-anchor" href="#قانون-مكافحة-الاحتكار" aria-label="Permalink to &quot;قانون مكافحة الاحتكار&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>47</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>مكافحة الاحتكار، المنافسة العادلة، النظام السوقي التكافلي، حظر الأفعال الافتراسية، ضمان تقدم عشرة آلاف عرق معاً</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون مكافحة الاحتكار</em> أحد القوانين الخمسة المساندة لحضارة التكافل المرساة. يهدف إلى منع أفعال الاحتكار والافتراس في موارد الزراعة والطوائف الزراعية والأسواق التجارية وغيرها من المجالات، والحفاظ على المنافسة العادلة والنظام السوقي التكافلي لكون هنغ يوان، وضمان «تقدم عشرة آلاف عرق معاً» بمنع أي قوة أو منظمة من اغتنام فرص التنمية عبر الاحتكار.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>المنافسة العادلة</td><td>تتنافس جميع الأطراف على قدم المساواة؛ ويُحظر إساءة استعمال المركز المهيمن والمنافسة غير العادلة</td></tr><tr><td>السوق المفتوح</td><td>يُحظر الاتفاقيات الاحتكارية وتقسيم الأسواق والقيود على المنافسة التي تستبعد أو تحد من المنافسة</td></tr><tr><td>حماية الضعيف</td><td>حماية مرجحة للمزارعين الجدد والأعراق المبتدئة والمنظمات الصغيرة والمتوسطة</td></tr><tr><td>النظام التكافلي</td><td>يجب أن يخدم السوق تقدم عشرة آلاف عرق معاً؛ ويُحظر نهب المصالح العامة من رأس المال والسلطة</td></tr><tr><td>التطبيق الموحد</td><td>يتولى تطبيق مكافحة الاحتكار جهة موحدة؛ ويُحظر الحمائية المحلية والأفعال الاحتكارية عبر الأبعاد</td></tr></tbody></table><h2 id="ثانياً-تعريف-الاحتكار" tabindex="-1">ثانياً: تعريف الاحتكار <a class="header-anchor" href="#ثانياً-تعريف-الاحتكار" aria-label="Permalink to &quot;ثانياً: تعريف الاحتكار&quot;">​</a></h2><p>يحدد هذا القانون الأفعال التالية كأفعال احتكارية، وهي محظورة:</p><ol><li><strong>الاتفاقيات الاحتكارية</strong>: اتفاقيات بين المنافسين أو بين المشغلين في المنبع والمصب بشأن تثبيت الأسعار وتقسيم الأسواق وتقييد الإنتاج والمقاطعة وغيرها.</li><li><strong>إساءة استعمال المركز المهيمن</strong>: إساءة استعمال المركز المهيمن في السوق للبيع بأسعار مرتفعة غير عادلة أو البيع بأقل من التكلفة أو فرض شروط معاملات غير معقولة أو رفض المعاملة أو البيع المربوط وغيرها.</li><li><strong>تركيز المشغلين</strong>: الاندماجات والاستحواذات والمشاريع المشتركة التي تلغي أو تقيد المنافسة، مع تقديم إقرار مسبق لجهة مكافحة الاحتكار للمراجعة.</li><li><strong>الاحتكار الإداري</strong>: إساءة استعمال السلطة الإدارية من الأجهزة الحكومية والمنظمات العامة لتقييد المنافسة، والحمائية المحلية والاحتكار القطاعي.</li><li><strong>احتكار موارد الزراعة</strong>: السيطرة الاحتكارية على موارد الزراعة وعُقد الطاقة الروحية والعوالم السرية، واستبعاد الآخرين من الزراعة.</li><li><strong>احتكار المواهب</strong>: استخدام وسائل غير عادلة للسيطرة الحصرية على مواهب الزراعة، وتقييد التدفق الحر للمواهب.</li></ol><h2 id="ثالثاً-أجهزة-مكافحة-الاحتكار" tabindex="-1">ثالثاً: أجهزة مكافحة الاحتكار <a class="header-anchor" href="#ثالثاً-أجهزة-مكافحة-الاحتكار" aria-label="Permalink to &quot;ثالثاً: أجهزة مكافحة الاحتكار&quot;">​</a></h2><p>تمارس محكمة التكافل وأجهزة تطبيق مكافحة الاحتكار التابعة لها الوظائف التالية:</p><table tabindex="0"><thead><tr><th>الجهاز</th><th>الوظيفة</th></tr></thead><tbody><tr><td>مكتب تطبيق مكافحة الاحتكار</td><td>التحقيق في أفعال الاحتكار، وفتح تحقيقات بشأن الأفعال المشتبه باحتكارها</td></tr><tr><td>لجنة مراجعة الاحتكار</td><td>مراجعة تركيز المشغلين وتغيرات هيكل السوق</td></tr><tr><td>مكتب مراقبة الأسعار</td><td>مراقبة السلوك السعري لموارد الزراعة والسلع المهمة</td></tr><tr><td>مكتب التنسيق عبر الأبعاد</td><td>تنسيق تطبيق مكافحة الاحتكار بين الأبعاد، ومنع الاحتكارات العابرة للأبعاد</td></tr></tbody></table><p>يتمتع جهاز تطبيق مكافحة الاحتكار بصلاحيات التحقيق: يمكنه مطالبة الأطراف المعنية بتقديم إيضاحات، وتفتيش الدفاتر والسجلات، ووضع الأختام على الأدلة ومصادرتها وغيرها. ويجب على الأطراف قيد التحقيق التعاون، ولا يجوز الرفض أو العرقلة.</p><h2 id="رابعاً-أحكام-خاصة-باحتكار-موارد-الزراعة" tabindex="-1">رابعاً: أحكام خاصة باحتكار موارد الزراعة <a class="header-anchor" href="#رابعاً-أحكام-خاصة-باحتكار-موارد-الزراعة" aria-label="Permalink to &quot;رابعاً: أحكام خاصة باحتكار موارد الزراعة&quot;">​</a></h2><p>موارد الزراعة ثروة عامة لكون هنغ يوان؛ ويضع هذا القانون أحكاماً خاصة بمنع احتكارها:</p><ol><li><strong>المساواة في الوصول إلى الموارد</strong>: لجميع الأعراق والمزارعين حقوق متساوية في الوصول إلى موارد الزراعة؛ ولا يجوز لأي طائفة أو منظمة شغل الموارد الجوهرية حصرياً.</li><li><strong>مشاركة عُقد الطاقة الروحية</strong>: تطبق عُقد الطاقة الروحية الرئيسية نظام إدارة مشتركة؛ ويُحظر الاحتلال الحصري وإنشاء جيوب زراعية خاصة.</li><li><strong>النظام المفتوح للعوالم السرية</strong>: العوالم السرية التي يكتشفها أي طرف يجب الإبلاغ عنها لجهة الإدارة وإدراجها في نظام الموارد العامة؛ ويُحظر الاحتلال السري.</li><li><strong>تنظيم سوق الحبوب</strong>: تطبق الحبوب المهمة والأدوية الروحية توجيهاً سعرياً وإشرافاً على العرض؛ ويُحظر الاحتكار والمضاربة على الأسعار.</li><li><strong>الإشراف على تداول الآثار</strong>: يجب تسجيل وإدارة تداول الآثار عالية المستوى؛ ويُحظر إنشاء احتكار آثار مسلحة عبر السيطرة على مصادر الآثار.</li></ol><h2 id="خامساً-سبل-الانتصاف-والمسؤولية-القانونية" tabindex="-1">خامساً: سبل الانتصاف والمسؤولية القانونية <a class="header-anchor" href="#خامساً-سبل-الانتصاف-والمسؤولية-القانونية" aria-label="Permalink to &quot;خامساً: سبل الانتصاف والمسؤولية القانونية&quot;">​</a></h2><p>بالنسبة للأفعال الاحتكارية، يوفر هذا القانون سبل الانتصاف والمسؤوليات التالية:</p><ul><li><strong>أمر الإيقاف</strong>: يصدر جهاز تطبيق مكافحة الاحتكار أمراً بوقف الأفعال الاحتكارية.</li><li><strong>الغرامات</strong>: تُفرض غرامات وفقاً للعائدات غير المشروعة وجسامة الظروف.</li><li><strong>مصادرة العائدات غير المشروعة</strong>: تُصادر العائدات غير المشروعة المكتسبة من الأفعال الاحتكارية.</li><li><strong>إلغاء الأهلية</strong>: في الحالات الجسيمة، تُلغى تراخيص الأعمال أو أهلية الطوائف الزراعية.</li><li><strong>تعويض الأضرار</strong>: للمتضررين من الأفعال الاحتكارية الحق في المطالبة بتعويض الأضرار.</li><li><strong>المسؤولية الجنائية</strong>: إذا شكل الفعل الاحتكاري جريمة، تُطبق المسؤولية الجنائية.</li></ul><h2 id="سادساً-الدعوى-العامة" tabindex="-1">سادساً: الدعوى العامة <a class="header-anchor" href="#سادساً-الدعوى-العامة" aria-label="Permalink to &quot;سادساً: الدعوى العامة&quot;">​</a></h2><p>بالنسبة للأفعال الاحتكارية الضارة بالمصالح العامة، يمكن للأطراف التالية رفع دعوى عامة لمكافحة الاحتكار أمام محكمة التكافل:</p><ul><li>أجهزة تطبيق مكافحة الاحتكار</li><li>منظمات المنفعة العامة التكافلية</li><li>الأطراف الأخرى المحددة قانوناً</li></ul><p>تهدف الدعوى العامة إلى وقف الأفعال الاحتكارية وحماية المصلحة العامة للنظام السوقي وتعويض الأضرار الواقعة على المصلحة العامة.</p><h2 id="سابعاً-تطبيق-القانون" tabindex="-1">سابعاً: تطبيق القانون <a class="header-anchor" href="#سابعاً-تطبيق-القانون" aria-label="Permalink to &quot;سابعاً: تطبيق القانون&quot;">​</a></h2><p>يسري هذا القانون على جميع الأفعال الاحتكارية الواقعة داخل كون هنغ يوان، بما في ذلك الأفعال الاحتكارية لأطراف من أكوان أخرى خاضعة لولاية كون هنغ يوان. وبالنسبة للأفعال الاحتكارية الواقعة عبر الأكوان، يُطبق مبدأ المعاملة بالمثل والتشاور.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون مكافحة الاحتكار</em> هو الحصن القانوني لفلسفة «تقدم عشرة آلاف عرق معاً» في حضارة التكافل المرساة. بتحديد الأفعال الاحتكارية ومعاقبتها، وإنشاء أجهزة متخصصة، وتنظيم احتكار موارد الزراعة، يضمن عدالة وانفتاح السوق التكافلي، ويمنع أي قوة من نهب الموارد وفرص التنمية، ويوفر ضمانات مؤسسية لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>42-消费者保护法 (قانون حماية المستهلك)</li><li>41-共生劳动法 (قانون العمل التكافلي)</li><li>07-联产承包机制详解 (الشرح المفصل لآلية التعاقد المشترك على الإنتاج)</li></ul>',29)])])}const p=a(d,[["render",i]]);export{c as __pageData,p as default};
